    // ─── DATA ASSEMBLY & CACHING ─────────────────────────────────────────────────

    function loadChunkedData(storageKey, chunks) {

        const cached = localStorage.getItem(storageKey);

        if (cached) {

            try {

                const parsed = JSON.parse(cached);

                if (parsed._v === EQUIP_LOOKUP_VERSION) return parsed.data;

            } catch(e) { /* re-init */ }

        }

        // First run or version mismatch — decode from embedded chunks

        const raw = chunks.join('');

        const data = JSON.parse(raw);

        const wrapper = { _v: EQUIP_LOOKUP_VERSION, data: data };

        try { localStorage.setItem(storageKey, JSON.stringify(wrapper)); } catch(e) {

            console.warn('[QCTI] localStorage quota exceeded for', storageKey);

        }

        return data;

    }

    // Initialize all three datasets

    const POSITIONS_DATA = loadChunkedData(POSITIONS_DATA_KEY, POSITION_CHUNKS);

    const ASSETS_DATA = loadChunkedData(ASSETS_DATA_KEY, ASSET_CHUNKS);

    const SYSTEMS_DATA = loadChunkedData(SYSTEMS_DATA_KEY, SYSTEM_CHUNKS);

