// HTML to insert (replaces the old Problem/Failure/Cause section):

const CLOSING_CODES_HTML = `

<div style="display:grid; grid-template-columns:1fr 1fr 1fr; gap:10px;">

    <div>

        <label style="font-size:12px; font-weight:600; color:#475569; text-transform:uppercase; letter-spacing:0.5px;">Problem Code</label>

        <select id="qcti-problem" style="width:100%; margin-top:4px; padding:10px; border:1px solid #d1d5db; border-radius:8px; font-size:13px; background:#fff;">

            <option value="">-- Select Problem --</option>

            ${Object.entries(CLOSING_CODES.problems).map(([code, p]) => 

                '<option value="' + code + '">' + code + ' - ' + p.label + '</option>'

            ).join('')}

        </select>

    </div>

    <div>

        <label style="font-size:12px; font-weight:600; color:#475569; text-transform:uppercase; letter-spacing:0.5px;">Failure Code</label>

        <select id="qcti-failure" style="width:100%; margin-top:4px; padding:10px; border:1px solid #d1d5db; border-radius:8px; font-size:13px; background:#fff;" disabled>

            <option value="">-- Select Failure --</option>

        </select>

    </div>

    <div>

        <label style="font-size:12px; font-weight:600; color:#475569; text-transform:uppercase; letter-spacing:0.5px;">Cause Code</label>

        <select id="qcti-cause" style="width:100%; margin-top:4px; padding:10px; border:1px solid #d1d5db; border-radius:8px; font-size:13px; background:#fff;" disabled>

            <option value="">-- Select Cause --</option>

        </select>

    </div>

</div>

`;

// ─── CASCADING JS LOGIC ────────────────────────────────────────────

// Call this after the form HTML is injected into the DOM.

function initClosingCodesCascade(panel) {

    const problemSelect = panel.querySelector('#qcti-problem');

    const failureSelect = panel.querySelector('#qcti-failure');

    const causeSelect = panel.querySelector('#qcti-cause');

    problemSelect.addEventListener('change', () => {

        const pCode = problemSelect.value;

        failureSelect.innerHTML = '<option value="">-- Select Failure --</option>';

        causeSelect.innerHTML = '<option value="">-- Select Cause --</option>';

        causeSelect.disabled = true;

        if (pCode && CLOSING_CODES.problems[pCode]) {

            const failures = CLOSING_CODES.problems[pCode].failures;

            Object.entries(failures).forEach(([fCode, f]) => {

                const opt = document.createElement('option');

                opt.value = fCode;

                opt.textContent = fCode + ' - ' + f.label;

                failureSelect.appendChild(opt);

            });

            failureSelect.disabled = false;

        } else {

            failureSelect.disabled = true;

        }

    });

    failureSelect.addEventListener('change', () => {

        const pCode = problemSelect.value;

        const fCode = failureSelect.value;

        causeSelect.innerHTML = '<option value="">-- Select Cause --</option>';

        if (pCode && fCode && CLOSING_CODES.problems[pCode]?.failures[fCode]) {

            const causeIndices = CLOSING_CODES.problems[pCode].failures[fCode].c;

            causeIndices.forEach(idx => {

                const cause = CLOSING_CODES.causes[idx];

                const opt = document.createElement('option');

                opt.value = cause.code;

                opt.textContent = cause.code + ' - ' + cause.label;

                causeSelect.appendChild(opt);

            });

            causeSelect.disabled = false;

        } else {

            causeSelect.disabled = true;

        }

    });

}

    // WO Execution options

    const WO_EXECUTION_OPTIONS = [

        { value: 'EXDN', label: 'EXDN — Executed during normal operation' },

        { value: 'EXOPS', label: 'EXOPS — Executed, agreed stop with OPS' },

        { value: 'EXSHUT', label: 'EXSHUT — Execution during Shutdown' },

        { value: 'EXDB', label: 'EXDB — Execution during the break' },

        { value: 'EXMW', label: 'EXMW — Execution in Maintenance Window' },

        { value: 'NEX', label: 'NEX — Not Executed' }

    ];

    // ═══════════════════════════════════════════════════════════════════

    // UTILITY FUNCTIONS

    // ═══════════════════════════════════════════════════════════════════

    function log(...args) {

        console.log(LOG_PREFIX, ...args);

    }

    function warn(...args) {

        console.warn(LOG_PREFIX, ...args);

    }

    function error(...args) {

        console.error(LOG_PREFIX, ...args);

    }

    function delay(ms) {

        return new Promise(resolve => setTimeout(resolve, ms));

    }

    /**

     * Smart wait: monitors Ext.Ajax.isLoading() and resolves when Ajax goes quiet.

     * Pattern from APM Master's zo() function.

     * @param {Object} Ext - Ext reference

     * @param {number} quietMs - How long Ajax must be idle before resolving (default 500)

     * @param {number} maxMs - Maximum wait time (default 8000)

     * @returns {Promise<number>} - Actual ms waited

     */

    // ═══════════════════════════════════════════════════════════════════

    // APM MASTER FOUNDATION HELPERS (verbatim ports from v14.18.15)

    // Author: RAI (on behalf of rbecks)

    // apmWaitAjax  = Be()  — event-driven wait: resolves the instant Ajax

    //                completes (50ms tail), only waits if actually loading,

    //                5s cap. Replaces blind `await delay(...)`.

    // apmDismissPopups = Mt()+lh()+dh()+ch() — auto-click "Yes" on EAM

    //                confirmation popups after a save; leaves non-confirmation

    //                (error) popups for the user. Prevents silent stalls.

    // apmSettle    = combined wait → dismiss → wait after a save.

    // CANONICAL: identical in both sim-t-auto-resolver and sim-t-jam-resolver.

    // All three accept EITHER a window OR an Ext object (auto-normalised).

    // ═══════════════════════════════════════════════════════════════════

    /** Normalise a window-or-Ext argument to the Ext object. */

    function apmToExt(winOrExt) {

        if (!winOrExt) return null;

        if (winOrExt.ComponentQuery && winOrExt.Ajax) return winOrExt; // already an Ext

        if (winOrExt.Ext) return winOrExt.Ext;                         // a window

        return winOrExt;                                               // best effort

    }

    /** Be(): wait until Ext.Ajax is not loading. Resolves fast when idle. */

    function apmWaitAjax(winOrExt, maxMs = 5000, tailMs = 50) {

        const Ext = apmToExt(winOrExt);

        if (!Ext || !Ext.Ajax) return delay(tailMs);

        if (!Ext.Ajax.isLoading()) return delay(tailMs);

        return new Promise((resolve) => {

            const off = () => { Ext.Ajax.un('requestcomplete', onDone); Ext.Ajax.un('requestexception', onDone); };

            const onDone = () => {

                if (!Ext.Ajax.isLoading()) { off(); clearTimeout(timer); setTimeout(resolve, tailMs); }

            };

            Ext.Ajax.on('requestcomplete', onDone);

            Ext.Ajax.on('requestexception', onDone);

            const timer = setTimeout(() => { off(); resolve(); }, maxMs);

        });

    }

    /** lh(): list visible message-box windows (excludes the record view). */

    function apmListPopups(Ext) {

        if (!Ext || !Ext.ComponentQuery) return [];

        try {

            return Ext.ComponentQuery.query('window:not([destroyed=true])').filter(

                (w) => w.isVisible && w.isVisible() && !(w.id && w.id.indexOf('recordview') !== -1)

            );

        } catch (e) { return []; }

    }

    /** dh(): classify a popup as confirmation (has yes+no) and return the yes button. */

    function apmClassifyPopup(win, Ext) {

        let yesBtn = null, noBtn = null;

        try {

            yesBtn = Ext.ComponentQuery.query('button[itemId=yes]:not([destroyed=true])', win).find((b) => b.isVisible && b.isVisible()) || null;

            noBtn = Ext.ComponentQuery.query('button[itemId=no]:not([destroyed=true])', win).find((b) => b.isVisible && b.isVisible()) || null;

        } catch (e) { /* ignore */ }

        // Also accept OK-only informational-confirmation dialogs (single OK button)

        if (!yesBtn) {

            try {

                yesBtn = Ext.ComponentQuery.query('button[itemId=ok]:not([destroyed=true])', win).find((b) => b.isVisible && b.isVisible()) || null;

            } catch (e) { /* ignore */ }

        }

        return { kind: (yesBtn && !yesBtn.disabled) ? 'confirmation' : 'non-confirmation', yesBtn, noBtn };

    }

    /** Mt(): auto-click "Yes"/"OK" on confirmation popups; leave error popups for the user.

     *  Returns true if at least one confirmation was dismissed. */

    async function apmDismissPopups(winOrExt) {

        const Ext = apmToExt(winOrExt);

        if (!Ext) return false;

        let dismissed = false;

        for (const popup of apmListPopups(Ext)) {

            const { kind, yesBtn } = apmClassifyPopup(popup, Ext);

            if (kind === 'confirmation' && yesBtn) {

                log('APM: auto-clicking "' + (yesBtn.text || yesBtn.itemId || 'Yes') + '" on confirmation popup');

                if (yesBtn.handler) yesBtn.handler.call(yesBtn.scope || yesBtn, yesBtn);

                else if (typeof yesBtn.fireEvent === 'function') yesBtn.fireEvent('click', yesBtn);

                await delay(300);

                if (!popup.isDestroyed && popup.isVisible && popup.isVisible()) {

                    warn('APM: popup persisted after auto-dismiss — may be a validation error');

                } else {

                    dismissed = true;

                }

            } else {

                let title = '';

                try { title = String(popup.title || '').trim(); } catch (e) {}

                warn('APM: non-confirmation popup left for user' + (title ? ' ("' + title + '")' : ''));

            }

        }

        return dismissed;

    }

    /** Combined save-settle: wait for Ajax, then auto-dismiss any confirmation popups,

     *  then wait for any follow-up Ajax the dismissal triggered. */

    async function apmSettle(winOrExt, maxMs = 8000) {

        await apmWaitAjax(winOrExt, maxMs);

        await apmDismissPopups(winOrExt);

        await apmWaitAjax(winOrExt, maxMs);

    }

    function waitForQuiet(Ext, quietMs = 500, maxMs = 8000) {

        return new Promise(resolve => {

            if (!Ext?.Ajax?.isLoading) { setTimeout(() => resolve(quietMs), quietMs); return; }

            if (!Ext.Ajax.isLoading()) { setTimeout(() => resolve(50), 50); return; }

            const start = performance.now();

            let quietStart = null;

            const check = () => {

                const elapsed = performance.now() - start;

                if (elapsed >= maxMs) { resolve(elapsed); return; }

                if (Ext.Ajax.isLoading()) {

                    quietStart = null;

                    setTimeout(check, 100);

                } else {

                    if (!quietStart) quietStart = performance.now();

                    if (performance.now() - quietStart >= quietMs) {

                        resolve(elapsed);

                    } else {

                        setTimeout(check, 50);

                    }

                }

            };

            check();

        });

    }

    /** Show a toast notification */

    function showToast(message, type = 'info', duration = 5000) {

        const targetDoc = window.top.document;

        let container = targetDoc.getElementById('qcti-resolve-toast-container');

        if (!container) {

            container = targetDoc.createElement('div');

            container.id = 'qcti-resolve-toast-container';

            Object.assign(container.style, {

                position: 'fixed', top: '20px', right: '20px', zIndex: '2147483647',

                display: 'flex', flexDirection: 'column', gap: '8px', pointerEvents: 'none'

            });

            targetDoc.body.appendChild(container);

        }

        const colors = {

            info: { bg: '#1e293b', border: '#3b82f6' },

            success: { bg: '#14532d', border: '#22c55e' },

            error: { bg: '#450a0a', border: '#ef4444' },

            warning: { bg: '#451a03', border: '#f59e0b' }

        };

        const c = colors[type] || colors.info;

        const toast = targetDoc.createElement('div');

        Object.assign(toast.style, {

            background: c.bg, border: `1px solid ${c.border}`, borderRadius: '8px',

            padding: '12px 18px', color: '#fff', fontSize: '14px', fontFamily: 'system-ui, sans-serif',

            boxShadow: '0 4px 20px rgba(0,0,0,0.4)', opacity: '0', transform: 'translateX(40px)',

            transition: 'all 0.3s ease', pointerEvents: 'auto', maxWidth: '360px'

        });

        toast.textContent = message;

        container.appendChild(toast);

        requestAnimationFrame(() => {

            toast.style.opacity = '1';

            toast.style.transform = 'translateX(0)';

        });

        setTimeout(() => {

            toast.style.opacity = '0';

            toast.style.transform = 'translateX(40px)';

            setTimeout(() => toast.remove(), 300);

        }, duration);

    }

    /** Create an overlay backdrop */

    function createOverlay(onClose) {

        const overlay = document.createElement('div');

        Object.assign(overlay.style, {

            position: 'fixed', top: '0', left: '0', width: '100vw', height: '100vh',

            background: 'rgba(0,0,0,0.6)', zIndex: '2147483640', display: 'flex',

            alignItems: 'center', justifyContent: 'center', fontFamily: 'system-ui, sans-serif'

        });

        overlay.addEventListener('click', (e) => {

            if (e.target === overlay && onClose) onClose();

        });

        document.body.appendChild(overlay);

        return overlay;

    }

    /** Remove all overlays */

    function removeOverlays() {

        document.querySelectorAll('[data-qcti-overlay]').forEach(el => el.remove());

    }

    // ═══════════════════════════════════════════════════════════════════

        function getTicketText() {

        // Get title — SIM-T uses various selectors depending on version

        const titleEl = document.querySelector(

            '[data-testid="ticket-title"], h1, [class*="ticket-title"], [class*="kat-label"]'

        );

        const title = titleEl ? titleEl.textContent : '';

        // Get body/description — SIM-T renders ticket content in the active tab panel

        // Try multiple approaches to capture all visible text

        let body = '';

        const selectors = [

            '[data-testid="ticket-description"]',

            '[class*="description"]',

            '[role="tabpanel"]',                    // Active tab content

            '[class*="ticket-body"]',

            '[class*="correspondence"]',

            'main', 'article',

            '.content-area'

        ];

        for (const sel of selectors) {

            const el = document.querySelector(sel);

            if (el && el.textContent.trim().length > 20) {

                body = el.textContent;

                break;

            }

        }

        log('getTicketText scraped:', (title + ' ' + body).substring(0, 200));

        return title + ' ' + body;

    }

    // Live-first ticket text (RAI on behalf of rbecks, v1.29.0).

    // SIM-T is a single-page app: cachedTicketText is captured once on initial page

    // load and goes stale when the user navigates to another ticket without a reload.

    // The old `cachedTicketText || getTicketText()` short-circuit therefore detected the

    // PREVIOUS ticket's equipment (off-by-one). Always scrape the live DOM first — the

    // ticket title (with its PLC token) is rendered live — and refresh the cache so any

    // later reader sees the current ticket too. Cache is only a last resort.

    function getCurrentTicketText() {

        const liveText = getTicketText();

        const text = (liveText && liveText.trim().length > 20) ? liveText : cachedTicketText;

        cachedTicketText = text;

        return text;

    }

    // ═══════════════════════════════════════════════════════════════════

    // SIM-T SIDE — TOOLBAR & UI

    // ═══════════════════════════════════════════════════════════════════

    function isSIMTPage() {

        return window.location.hostname === 't.corp.amazon.com';

    }

    function isAPMPage() {

        return window.location.hostname === 'eu1.eam.hxgnsmartcloud.com';

    }

    function getTicketId() {

        // Match both formats: D481056730 (letter+digits) and SIM-12345 (prefix-digits)

        const match = window.location.pathname.match(/\/([A-Z]+-\d+|[A-Z]\d+)/);

        return match ? match[1] : null;

    }

    function createToolbar() {

        // Coexistence: if the shared toolbar already exists (e.g. the jam resolver

        // created it first), don't bail — ensure OUR buttons are present in it.

        if (document.getElementById('qcti-resolve-toolbar')) { buildToolbarButtons(); return; }

        // Try to inject immediately, or watch for the element to appear

        if (!tryInjectToolbar()) {

            // If the badge hasn't rendered yet (React async), observe DOM changes

            log('Badge not found yet — watching for it...');

            const observer = new MutationObserver(() => {

                if (tryInjectToolbar()) {

                    observer.disconnect();

                }

            });

            observer.observe(document.body, { childList: true, subtree: true });

            // Give up after 10 seconds and use fallback

            setTimeout(() => {

                observer.disconnect();

                if (!document.getElementById('qcti-resolve-toolbar')) {

                    log('Badge never appeared — using fallback position');

                    injectToolbarFallback();

                }

            }, 10000);

        }

    }

    function buildToolbarButtons() {

        // Reuse the shared toolbar if another qcti script already created it, else make it.

        // Each button carries a stable id so auto + jam never duplicate a button and each

        // script adds only the ones it owns.

        let toolbar = document.getElementById('qcti-resolve-toolbar');

        if (!toolbar) {

            toolbar = document.createElement('span');

            toolbar.id = 'qcti-resolve-toolbar';

            Object.assign(toolbar.style, {

                display: 'inline-flex', gap: '6px', marginLeft: '10px', verticalAlign: 'middle'

            });

        }

        const BTN_STYLE = {

            color: '#f9f9fa', border: 'none', borderRadius: '4px',

            padding: '0 8px', fontSize: '12px', fontWeight: '400', cursor: 'pointer',

            transition: 'all 0.2s', lineHeight: '20px', letterSpacing: '.005em',

            fontFamily: '"Amazon Ember", "Helvetica Neue", Roboto, Arial, sans-serif',

            display: 'inline-block'

        };

        if (!document.getElementById('qcti-btn-quick')) {

            const quickBtn = document.createElement('button');

            quickBtn.id = 'qcti-btn-quick';

            quickBtn.innerHTML = '⚡ Quick';

            Object.assign(quickBtn.style, BTN_STYLE, { background: '#2563eb' });

            quickBtn.addEventListener('mouseenter', () => quickBtn.style.background = '#1d4ed8');

            quickBtn.addEventListener('mouseleave', () => quickBtn.style.background = '#2563eb');

            quickBtn.addEventListener('click', handleQuickResolve);

            toolbar.appendChild(quickBtn);

        }

        if (!document.getElementById('qcti-btn-custom')) {

            const customBtn = document.createElement('button');

            customBtn.id = 'qcti-btn-custom';

            customBtn.innerHTML = '📋 Custom';

            Object.assign(customBtn.style, BTN_STYLE, { background: '#16a34a' });

            customBtn.addEventListener('mouseenter', () => customBtn.style.background = '#15803d');

            customBtn.addEventListener('mouseleave', () => customBtn.style.background = '#16a34a');

            customBtn.addEventListener('click', () => showCustomResolveForm());

            toolbar.appendChild(customBtn);

        }

        if (!document.getElementById('qcti-btn-jam')) {

            const jamBtn = document.createElement('button');

            jamBtn.id = 'qcti-btn-jam';

            jamBtn.innerHTML = '🔧 Jam';

            Object.assign(jamBtn.style, BTN_STYLE, { background: '#dc2626' });

            jamBtn.addEventListener('mouseenter', () => jamBtn.style.background = '#b91c1c');

            jamBtn.addEventListener('mouseleave', () => jamBtn.style.background = '#dc2626');

            jamBtn.addEventListener('click', handleJamResolve);

            toolbar.appendChild(jamBtn);

        }

        return toolbar;

    }

    function tryInjectToolbar() {

        if (document.getElementById('qcti-resolve-toolbar')) { buildToolbarButtons(); return true; }

        // Look for the "Assisted by AI" badge

        const allElements = document.querySelectorAll('span, div, button, a, label');

        for (const el of allElements) {

            const text = el.textContent.trim();

            if (text.includes('Assisted by AI') && el.offsetWidth > 0 && el.offsetWidth < 250) {

                const toolbar = buildToolbarButtons();

                el.parentElement.insertBefore(toolbar, el.nextSibling);

                log('Toolbar injected next to "Assisted by AI" badge');

                return true;

            }

        }

        // Try summary element containing "synopsis"

        const summaries = document.querySelectorAll('summary');

        for (const summary of summaries) {

            if (summary.textContent.toLowerCase().includes('synopsis')) {

                const toolbar = buildToolbarButtons();

                summary.appendChild(toolbar);

                log('Toolbar injected into synopsis summary');

                return true;

            }

        }

        return false;

    }

    function injectToolbarFallback() {

        if (document.getElementById('qcti-resolve-toolbar')) { buildToolbarButtons(); return; }

        const toolbar = buildToolbarButtons();

        // Position near where "Assisted by AI" would be

        Object.assign(toolbar.style, {

            position: 'fixed', top: '230px', left: '470px', zIndex: '2147483640',

            display: 'flex', gap: '6px', padding: '5px 12px',

            background: 'rgba(255,255,255,0.97)', borderRadius: '8px',

            boxShadow: '0 2px 10px rgba(0,0,0,0.12)', border: '1px solid #e2e8f0'

        });

        document.body.appendChild(toolbar);

        log('Toolbar created (fixed fallback near synopsis area)');

    }

    const TEMPLATES_KEY = 'qcti_resolve_templates'; // Array of {name, data}

    function getTemplates() {

        try { return JSON.parse(localStorage.getItem(TEMPLATES_KEY)) || []; }

        catch(e) { return []; }

    }

    function saveTemplates(templates) {

        localStorage.setItem(TEMPLATES_KEY, JSON.stringify(templates));

    }

